using System;
class DongVat {
    public string Ten;
    public DongVat(string t) { Ten = t; }
    public virtual string Keu() => Ten + " keu";
}
class Cho : DongVat {
    public Cho(string t) : base(t) {}
    public override string Keu() => Ten + " sua gau gau";
}
class Program {
    static void Main() {
        Console.WriteLine(new Cho("Mun").Keu());
    }
}
